begin;
with j as (select * from jsonb_to_recordset($law7d0065$[{"code_id":"NK_RF","article_number":"86","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 23.07.2013 № 248-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n1) российским организациям, иностранным некоммерческим неправительственным организациям, осуществляющим деятельность на территории Российской Федерации через отделения, аккредитованным филиалам, представительствам иностранных организаций, индивидуальным предпринимателям - при наличии сведений о соответствующих идентификационном номере налогоплательщика, коде причины постановки на учет в налоговом органе, дате постановки на учет в налоговом органе, содержащихся соответственно в Едином государственном реестре юридических лиц, государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, Едином государственном реестре индивидуальных предпринимателей;\n\n2) нотариусам, занимающимся частной практикой, адвокатам, учредившим адвокатские кабинеты, - при наличии сведений об идентификационном номере налогоплательщика, иностранным организациям, не указанным в подпункте 1 настоящего пункта, - при наличии сведений об идентификационном номере налогоплательщика, коде причины постановки на учет в налоговом органе и дате постановки на учет в налоговом органе, содержащихся в Едином государственном реестре налогоплательщиков. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 241-ФЗ)\n\nИнформация сообщается в электронной форме в течение трех дней со дня соответствующего события, если иное не предусмотрено настоящей статьей.\n\nПорядок сообщения банком, оператором платформы цифрового рубля об открытии или о закрытии счета, вклада (депозита), счета цифрового рубля, об изменении реквизитов счета, вклада (депозита), счета цифрового рубля организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, о предоставлении права или прекращении права организации, индивидуального предпринимателя использовать корпоративные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица использовать персонифицированные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица, в отношении которого в соответствии с законодательством Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма проведена упрощенная идентификация, использовать неперсонифицированные электронные средства платежа для переводов электронных денежных средств, а также об изменении реквизитов электронных средств платежа, перечисленных в настоящем пункте, в электронной форме устанавливается Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nФормы и форматы сообщений банка, оператора платформы цифрового рубля налоговому органу об открытии или о закрытии счета, вклада (депозита), счета цифрового рубля организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, об изменении реквизитов счета, вклада (депозита), счета цифрового рубля, о предоставлении права или прекращении права организации, индивидуального предпринимателя использовать корпоративные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица использовать персонифицированные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица, в отношении которого в соответствии с законодательством Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма проведена упрощенная идентификация, использовать неперсонифицированные электронные средства платежа для переводов электронных денежных средств, а также об изменении реквизитов электронных средств платежа, перечисленных в настоящем пункте, устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, а в отношении счета цифрового рубля - указанным федеральным органом исполнительной власти по согласованию с Центральным банком Российской Федерации. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 241-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств (драгоценных металлов) на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) организаций, индивидуальных предпринимателей в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств и о переводах электронных денежных средств могут быть запрошены налоговыми органами в случаях проведения налоговых проверок (налогового мониторинга) указанных лиц либо истребования у них документов (информации) в соответствии со статьей 931 настоящего Кодекса, а также в случаях неисполнения требования об уплате задолженности, вынесения решения о взыскании задолженности, принятия решений о приостановлении операций по счетам, счетам цифрового рубля организации, индивидуального предпринимателя, приостановлении переводов электронных денежных средств или об отмене приостановления операций по счетам, счетам цифрового рубля организации, индивидуального предпринимателя, отмене приостановления переводов электронных денежных средств. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств (драгоценных металлов) на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) физических лиц, не являющихся индивидуальными предпринимателями, в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств и о переводах электронных денежных средств могут быть запрошены налоговыми органами в случаях вынесения решения о взыскании задолженности либо при наличии согласия руководителя вышестоящего налогового органа или руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в случаях проведения налоговых проверок в отношении этих лиц либо истребования у них документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса. (В редакции  федеральных законов от 19.12.2023 № 610-ФЗ, от 31.07.2025 № 287-ФЗ)\n\nНалоговыми органами могут быть запрошены справки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) организаций, индивидуальных предпринимателей и физических лиц, не являющихся индивидуальными предпринимателями, в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств, цифровых рублей и о переводах электронных денежных средств индивидуальных предпринимателей и физических лиц, не являющихся индивидуальными предпринимателями, соответственно в банке, у оператора платформы цифрового рубля на основании запроса уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам), счетам цифрового рубля иностранных организаций, реорганизованных или ликвидированных организаций могут быть запрошены налоговыми органами соответственно в банках, у оператора платформы цифрового рубля, если указанные организации являлись участниками сделки (операции) и (или) совокупности сделок (операций) с лицом, в отношении которого проводится налоговая проверка (налоговый мониторинг) либо у которого истребуются документы (информация) в соответствии со статьей 931 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов организации, индивидуального предпринимат\n\nеля, физического лица, не являющегося индивидуальным предпринимателем, могут быть запрошены налоговыми органами в случае, если в заявлении о распоряжении путем возврата в соответствии с настоящим Кодексом денежных средств указан счет, сведения о котором не представлены в налоговый орган в соответствии с пунктом 11 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nКопии документов (информация), указанные в абзаце первом настоящего пункта, могут быть запрошены налоговыми органами:\n\nв отношении организации (индивидуального предпринимателя) - в случаях проведения налоговой проверки (налогового мониторинга) в отношении этого лица, истребования у него документов (информации) в соответствии со статьей 931 настоящего Кодекса, вынесения в отношении этого лица решения о взыскании задолженности и (или) принятия решения о приостановлении операций по счетам, счету цифрового рубля этого лица, решения о приостановлении переводов его электронных денежных средств, решения об отмене приостановления операций по счетам, счету цифрового рубля этого лица и (или) решения об отмене приостановления переводов электронных денежных средств этого лица; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 19.12.2023 № 610-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nв отношении физического лица, не являющегося индивидуальным предпринимателем, - при наличии согласия руководителя вышестоящего налогового органа или руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в случаях проведения налоговой проверки в отношении этого лица либо истребования у него документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса;\n\nв отношении организации (индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем) - на основании запроса уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации.\n\nЕсли запрашиваемые документы (информация) не могут быть представлены в указанные в настоящем пункте сроки, налоговый орган при получении от банка уведомления о невозможности представления в установленные сроки документов (информации) и о сроках (при необходимости), в течение которых эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ течение двух дней со дня получения такого уведомления руководитель (заместитель руководителя) налогового органа вправе на основании этого уведомления продлить сроки представления документов или отказать в продлении сроков, о чем выносится отдельное решение. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nФорма, формат указанного уведомления и порядок его направления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nФорма и порядок представления банками, оператором платформы цифрового рубля в электронной форме информации по запросам налоговых органов устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации. (В редакции  федеральных законов от 03.07.2016 № 240-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nФорматы представления банками, оператором платформы цифрового рубля в электронной форме информации по запросам налоговых органов утверждаются Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  федеральных законов от 29.06.2012 № 97-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nПравила, предусмотренные настоящей статьей, применяются также в отношении счетов инвестиционного товарищества, открываемых участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, для осуществления операций, связанных с ведением общих дел товарищей по договору инвестиционного товарищества, и в отношении корпоративных электронных средств платежа, используемых для переводов электронных денежных средств по таким операциям, а также в отношении их счетов цифрового рубля. (Дополнение абзацем - Федеральный закон от 28.11.2011 № 336-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 27.06.2011 № 162-ФЗ)\n\nОбязанности, предусмотренные пунктом 2 настоящей статьи, исполняются также кредитной организацией, у которой отозвана лицензия на осуществление банковских операций, до дня внесения в Единый государственный реестр юридических лиц записи о ликвидации такой организации в течение семи дней со дня получения мотивированного запроса налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)","article_title":"Статья 86. Обязанности банков, оператора платформы цифрового рубля, связанные с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"099ce5ab641328037330076d68ac473718572b473619d516e50b44d9eaf76765"},{"code_id":"NK_RF","article_number":"86.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"250b91848e696a7ad1d9f0b88aa62fbf1459f45f4420b8685db320c6e3ee176a"},{"code_id":"NK_RF","article_number":"86.2","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.2. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"250b91848e696a7ad1d9f0b88aa62fbf1459f45f4420b8685db320c6e3ee176a"},{"code_id":"NK_RF","article_number":"86.3","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.3. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58ab009ca066017547e39ea5e140f03c4ee439d7aa0e6b40e2f620220c96bd67"},{"code_id":"NK_RF","article_number":"86.4","version_date":"2000-07-31","article_text":"1. Фонд пенсионного и социального страхования Российской Федерации обязан не позднее 10-го числа каждого месяца представлять в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения за предшествующий месяц о лицах, распорядившихся средствами (частью средств) материнского (семейного) капитала в целях улучшения жилищных условий, и сумме перечисленных средств.\n\n2. Формы, форматы представляемых в электронной форме в налоговые органы сведений, предусмотренных настоящей статьей, и порядок заполнения форм утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 86.4. Обязанности органов, учреждений, организаций представлять в налоговые органы сведения, связанные с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb54c390cce93d7e968c019423c6fcbbc637ed0629f4fc0e228dfb260a4d2911"},{"code_id":"NK_RF","article_number":"86.5","version_date":"2000-07-31","article_text":"1. Оператор майнинговой инфраструктуры обязан сообщать в налоговый орган по месту своего нахождения сведения, связанные с осуществлением майнинга цифровой валюты лицом, которому данный оператор оказывает услуги по предоставлению майнинговой инфраструктуры. Состав таких сведений определяется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Сведения, указанные в пункте 1 настоящей статьи, направляются в электронной форме по телекоммуникационным каналам связи не позднее 25-го числа месяца, следующего за истекшим кварталом, по формату, утвержденному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 29.11.2024 № 418-ФЗ)","article_title":"Статья 86.5. Обязанность оператора майнинговой инфраструктуры, связанная с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e36c6c0ca277de29789e7169e44dad6a3eae369818226b7950ae8be99725f9e3"},{"code_id":"NK_RF","article_number":"87","version_date":"2000-07-31","article_text":"1) камеральные налоговые проверки;\n\n2) выездные налоговые проверки.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 87. Налоговые проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdd8abcac590c00ec8bb2a790973832a79fa4e0310a4f04069a983dce3722c22"},{"code_id":"NK_RF","article_number":"87.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Таможенный кодекс Российской Федерации от 28.05.2003 № 61-ФЗ)","article_title":"Статья 87.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74dcb52b7d79192a049d0fab7e1c5f8904e1084a804608e6744cf40318a4d7a5"},{"code_id":"NK_RF","article_number":"88","version_date":"2000-07-31","article_text":"Камеральная налоговая проверка расчета финансового результата инвестиционного товарищества проводится налоговым органом по месту учета участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета). (Дополнение абзацем - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n12. В случае, если налоговая декларация по налогу на доходы физических лиц в отношении доходов, полученных налогоплательщиком от продажи либо в результате дарения недвижимого имущества, не представлена в налоговый орган в установленный срок в соответствии с подпунктом 2 пункта 1 и пунктом 3 статьи 228, пунктом 1 статьи 229 настоящего Кодекса, камеральная налоговая проверка проводится в соответствии с настоящей статьей на основе имеющихся у налоговых органов документов (информации) о таком налогоплательщике и об указанных доходах.\n\nПри наличии обстоятельств, указанных в абзаце первом настоящего пункта, камеральная налоговая проверка проводится в течение трех месяцев со дня, следующего за днем истечения установленного срока уплаты налога по соответствующим доходам.\n\nПри проведении в соответствии с абзацем первым настоящего пункта камеральной налоговой проверки налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения.\n\nВ случае, если до окончания проведения в соответствии с абзацем первым настоящего пункта камеральной налоговой проверки налогоплательщиком (его представителем) представлена налоговая декларация, указанная в абзаце первом настоящего пункта, камеральная налоговая проверка прекращается и начинается новая камеральная налоговая проверка на основе представленной налоговой декларации. При этом документы (информация), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки и иных мероприятий налогового контроля в отношении такого налогоплательщика, могут быть использованы при проведении камеральной налоговой проверки на основе представленной налоговой декларации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налоговая декларация (расчет) не представлена налогоплательщиком - контролирующим лицом организации, признаваемым таковым в соответствии с главой 34 настоящего Кодекса, или иностранным лицом, подлежащим постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, в налоговый орган в установленный срок, уполномоченные должностные лица налогового органа вправе провести камеральную налоговую проверку на основе имеющихся у них документов (информации) о налогоплательщике, а также данных об иных аналогичных налогоплательщиках в течение трех месяцев (в течение шести месяцев для иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса) со дня истечения срока представления такой налоговой декларации (расчета), установленного законодательством о налогах и сборах. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 244-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки имеющихся у налогового органа документов (информации) налогоплательщиком представлена налоговая декларация, камеральная налоговая проверка прекращается и начинается новая камеральная налоговая проверка на основе представленной налоговой декларации. Прекращение камеральной налоговой проверки означает прекращение всех действий налогового органа в отношении имеющихся у налогового органа документов (информации). При этом документы (информация), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки, могут быть использованы при проведении мероприятий налогового контроля в отношении налогоплательщика. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nКамеральная налоговая проверка на основе налоговой декларации по налогу на добавленную стоимость, документов, представленных в налоговый орган, а также других документов о деятельности налогоплательщика, имеющихся у налогового органа, проводится в течение двух месяцев со дня представления такой налоговой декларации (в течение шести месяцев со дня представления иностранным лицом, состоящим на учете в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, налоговой декларации по налогу на добавленную стоимость). (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки налоговой декларации по налогу на добавленную стоимость налоговым органом установлены признаки, указывающие на возможное нарушение законодательства о налогах и сборах, руководитель (заместитель руководителя) налогового органа вправе принять решение о продлении срока проведения камеральной налоговой проверки. Срок камеральной налоговой проверки может быть продлен до трех месяцев со дня представления налоговой декларации по налогу на добавленную стоимость (за исключением камеральной налоговой проверки налоговой декларации по налогу на добавленную стоимость, представленной иностранным лицом, состоящим на учете в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса). (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nКамеральная налоговая проверка на основе заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса, проводится в течение 30 календарных дней со дня представления такого заявления, если иное не установлено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки на основе заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса, налоговым органом установлены признаки, указывающие на возможное нарушение законодательства о налогах и сборах, руководитель (заместитель руководителя) налогового органа вправе принять решение о продлении срока проведен\n\nия камеральной налоговой проверки. Срок проведения камеральной налоговой проверки может быть продлен до трех месяцев со дня представления заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nРешение о продлении срока проведения камеральной налоговой проверки направляется налогоплательщику через личный кабинет налогоплательщика (при прекращении у налогоплательщика доступа к личному кабинету налогоплательщика - по почте заказным письмом) в срок, не превышающий трех дней с даты принятия такого решения. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nКамеральная налоговая проверка лиц, указанных в пункте 2 статьи 80 настоящего Кодекса, представивших единую (упрощенную) налоговую декларацию, проводится в течение трех месяцев на основе имеющихся у налоговых органов документов (информации) о налогоплательщике с учетом следующих особенностей: (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nкамеральная налоговая проверка проводится за налоговые периоды истекшего календарного года начиная с 1 февраля следующего календарного года; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nв случае принятия решения о реорганизации или ликвидации организации камеральная налоговая проверка проводится за истекшие налоговые периоды текущего календарного года со дня, следующего за днем внесения в единый государственный реестр юридических лиц записи о том, что такая организация находится в процессе реорганизации или ликвидации. Ликвидация организации не может быть завершена ранее окончания камеральной налоговой проверки. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\nПри проведении камеральной налоговой проверки на основе уточненной налоговой декларации (расчета), в которой уменьшена сумма налога, подлежащая уплате в бюджетную систему Российской Федерации, по сравнению с ранее представленной налоговой декларацией (расчетом), налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения, обосновывающие изменение соответствующих показателей налоговой декларации (расчета). (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 04.11.2014 № 348-ФЗ)\n\nПри проведении камеральной налоговой проверки налоговой декларации (расчета), в которой заявлена сумма полученного в соответствующем отчетном (налоговом) периоде убытка, налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения, обосновывающие размер полученного убытка. (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nНалогоплательщики, на которых настоящим Кодексом возложена обязанность представлять налоговую декларацию по налогу на добавленную стоимость в электронной форме, при проведении камеральной налоговой проверки такой налоговой декларации представляют пояснения, предусмотренные настоящим пунктом, в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота по формату, установленному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. При представлении указанных пояснений не по формату, установленному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или на бумажном носителе такие пояснения не считаются представленными. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\nНалогоплательщик вправе в качестве пояснения представить в электронной форме реестр подтверждающих документов. Форма и порядок заполнения указанного реестра, а также формат и порядок представления такого реестра в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nНалоговый орган вправе истребовать у налогоплательщика документы, подтверждающие в соответствии со статьей 172 настоящего Кодекса правомерность применения налоговых вычетов.\n\n1) подтверждающие, что местом оказания услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса, признается территория Российской Федерации, а также иную информацию (сведения) относительно таких услуг;\n\n2) подтверждающие, что местом реализации товаров физическим лицам посредством электронной торговой площадки в соответствии со статьей 1743 настоящего Кодекса признается территория Российской Федерации, а также иную информацию (сведения) относительно таких товаров.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n1) между сведениями, содержащимися в налоговой декларации, представленной налогоплательщиком в соответствии с пунктом 2 статьи 80 и главами 261 и 262 настоящего Кодекса, и сведениями, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, и (или) документах, содержащих реквизиты прослеживаемости, представленных в налоговый орган налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости;\n\n2) между сведениями об операциях, содержащимися в налоговой декларации по налогу на добавленную стоимость, представленной налогоплательщиком, и сведениями об указанных операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном в налоговый орган другим налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости;\n\n3) между сведениями об операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости, и сведениями об указанных операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном в налоговый орган другим налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости.\n\nПри этом налоговый орган не вправе истребовать у налогоплательщика счета-фактуры, первичные и иные документы, относящиеся к операциям с товарами, подлежащими прослеживаемости, при выявлении несоответствий, указанных в настоящем пункте, если такие документы ранее представлялись в налоговый орган в случаях и порядке, которые установлены Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\nКамеральная налоговая проверка на основе налоговой декларации (расчета), по которой налоговым органом в соответствии с пунктом 42 статьи 80 настоящего Кодекса налогоплательщику направлено уведомление о признании налоговой декларации (расчета) непредставленной, прекращается в день направления указанного уведомления.\n\nЕсли указанная в абзаце втором настоящего пункта налоговая декларация (расчет) была уточненной, то по ранее представленной в налоговый орган налогоплательщиком налоговой декларации (расчету) камеральная налоговая проверка возобновляется. В этом случае в срок проведения камеральной налоговой проверки по ранее представленной налоговой декларации (расчету) не включается срок камеральной налоговой проверки, прекращенной в соответствии с абзацем вторым настоящего пункта.\n\nПрекращение камеральной налоговой проверки означает прекращение всех действий налогового органа в отношении ранее представленной налоговой декларации (расчета). При этом документы (сведения), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки, могут быть использованы при проведении мероприятий налогового контроля в отношении налогоплательщика.\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n11. Ка\n\nмеральная налоговая проверка по консолидированной группе налогоплательщиков проводится в порядке, установленном настоящей статьей, на основе налоговых деклараций (расчетов) и документов, представленных ответственным участником этой группы, а также других документов о деятельности этой группы, имеющихся у налогового органа.\n\nПри проведении камеральной налоговой проверки по консолидированной группе налогоплательщиков налоговый орган вправе истребовать у ответственного участника этой группы копии документов, которые должны представляться с налоговой декларацией по налогу на прибыль организаций по консолидированной группе налогоплательщиков в соответствии с главой 25 настоящего Кодекса, в том числе относящиеся к деятельности иных участников проверяемой группы.\n\nНеобходимые пояснения и документы по консолидированной группе налогоплательщиков налоговому органу представляет ответственный участник этой группы.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 88. Камеральная налоговая проверка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"653c547fd894b01a6f91f7edfd6b5d4541e64f2aa952ce407d54c70198c54435"},{"code_id":"NK_RF","article_number":"89","version_date":"2000-07-31","article_text":"1. Выездная налоговая проверка проводится на территории (в помещении) налогоплательщика на основании решения руководителя (заместителя руководителя) налогового органа.\n\nВ случае, если у налогоплательщика отсутствует возможность предоставить помещение для проведения выездной налоговой проверки, выездная налоговая проверка может проводиться по месту нахождения налогового органа, а в случае проведения выездной налоговой проверки налогоплательщиков - иностранных организаций, признаваемых налоговыми резидентами Российской Федерации в порядке, установленном пунктом 8 статьи 2462 настоящего Кодекса, - по месту нахождения обособленного подразделения такой организации. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nРешение о проведении выездной налоговой проверки налогоплательщика, отнесенного в порядке, установленном статьей 83 настоящего Кодекса, к категории крупнейших налогоплательщиков, выносит налоговый орган, осуществивший постановку этого налогоплательщика на учет в качестве крупнейшего налогоплательщика. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nСамостоятельная выездная налоговая проверка филиала или представительства проводится на основании решения налогового органа по месту нахождения такого обособленного подразделения или налогового органа, уполномоченного на проведение выездных налоговых проверок на территории субъекта Российской Федерации филиалов и представительств, имеющих место нахождения на территории этого субъекта Российской Федерации. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nРешение о проведении выездной налоговой проверки должно содержать следующие сведения:\n\nполное и сокращенное наименования либо фамилия, имя, отчество налогоплательщика;\n\nпредмет проверки, то есть налоги, правильность исчисления и уплаты которых подлежит проверке;\n\nпериоды, за которые проводится проверка;\n\nдолжности, фамилии и инициалы сотрудников налогового органа, которым поручается проведение проверки.\n\nФорма решения руководителя (заместителя руководителя) налогового органа о проведении выездной налоговой проверки утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nРешение о проведении выездной налоговой проверки не может быть вынесено на основе специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений, а также сведений, содержащихся в указанной специальной декларации и (или) документах. (Дополнение абзацем - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.09.2010 № 243-ФЗ)\n\nВ рамках выездной налоговой проверки может быть проверен период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении проверки, если иное не предусмотрено настоящим Кодексом. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 30.09.2013 № 267-ФЗ)\n\nВ случае представления налогоплательщиком уточненной налоговой декларации в рамках соответствующей выездной налоговой проверки проверяется период, за который представлена уточненная налоговая декларация. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nНалоговые органы не вправе проводить в отношении одного налогоплательщика более двух выездных налоговых проверок в течение календарного года, за исключением случаев принятия решения руководителем федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о необходимости проведения выездной налоговой проверки налогоплательщика сверх указанного ограничения.\n\nПри определении количества выездных налоговых проверок налогоплательщика не учитывается количество проведенных самостоятельных выездных налоговых проверок его филиалов и представительств.\n\n1) проведение выездной налоговой проверки вышестоящим налоговым органом - в порядке контроля за деятельностью налогового органа, проводившего налоговый мониторинг;\n\n2) досрочное прекращение налогового мониторинга;\n\n3) невыполнение налогоплательщиком мотивированного мнения (мотивированных мнений) налогового органа в срок до 1 декабря года, следующего за периодом, за который проводился налоговый мониторинг, или в случае приостановления течения срока направления мотивированного мнения по запросу такого налогоплательщика для получения разъяснений в соответствии с пунктом 5 статьи 10530 настоящего Кодекса по вопросам применения законодательства о налогах и сборах в более поздний срок, равный периоду такого приостановления, исчисляемому со дня получения таким налогоплательщиком указанного мотивированного мнения. В этом случае решение о проведении выездной налоговой проверки выносится налоговым органом не позднее двух месяцев со дня истечения указанного срока. Предметом такой выездной налоговой проверки являются правильность исчисления и своевременность уплаты налогов (сборов, страховых взносов) в соответствии с невыполненным мотивированным мнением (невыполненными мотивированными мнениями); (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n4) представление налогоплательщиком в календарном году, за который налоговый мониторинг не проводится, уточненной налоговой декларации (расчета) за период проведения налогового мониторинга, в которой по сравнению с ранее представленной налоговой декларацией (расчетом) уменьшена сумма налога (сбора, страховых взносов), подлежащая уплате в бюджетную систему Российской Федерации, увеличена заявленная к возмещению сумма налога на добавленную стоимость или акциза либо увеличена сумма полученного убытка. Предметом выездной налоговой проверки в указанном случае является правильность исчисления налога (сбора, страховых взносов) (определения суммы убытка) на основании измененных показателей уточненной налоговой декларации (расчета), повлекших уменьшение ранее исчисленной суммы налога (сбора, страховых взносов) (увеличение заявленной к возмещению суммы налога на добавленную стоимость или акциза либо увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 04.11.2014 № 348-ФЗ)\n\nОснования и порядок продления срока проведения выездной налоговой проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nНалоговый орган вправе проводить самостоятельную выездную налоговую проверку филиалов и представительств по вопросам правильности исчисления и своевременности уплаты региональных и (или) местных налогов.\n\nНалоговый орган, проводящий самостоятельную выездную проверку филиалов и представительств, не вправе проводить в отношении филиала или представительства две и более выездные налоговые проверки по одним и тем же налогам за один и тот же период.\n\nНалоговый орган не вправе проводить в отношении одного филиала или представительства налогоплательщика более двух выездных налоговых проверок в течение одного календарного года.\n\nПри проведении самостоятельной выездной налоговой проверки филиалов и представительств налогоплательщика срок проверки не может превышать один месяц.\n\nВ случае, если выездная налоговая проверка проводится в отношении налогоплательщика, не являющегося управляющим товарищем, ответственным за ведение налогового учета (далее в настоящей статье - управляющий товарищ), требование о представлении документов и (или) информации, связанных с его участием в договоре инвестиционного товарищества, направляется управляющему товарищу. Если управляющий товарищ не представил документы и (или) информацию в установленный срок, требование о представлении документов и (или) информации, связанных с участием проверяемого налогоплательщика в инвестиционном товариществе, может быть направлено другим участникам договора инвестиционного товарищества.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n1) истребования документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса;\n\n2) получения информации от иностранных государственных органов в рамках международных договоров Российской Федерации;\n\n3) проведения экспертиз;\n\n4) перевода на русский язык документов, представленных налогоплательщиком на иностранном языке.\n\nПриостановление проведения выездной налоговой проверки по основанию, указанному в подпункте 1 настоящего пункта, допускается не более одного раза по каждому лицу, у которого истребуются документы.\n\nПриостановление и возобновление проведения выездной налоговой проверки оформляются соответствующим решением руководителя (заместителя руководителя) налогового органа, проводящего указанную проверку.\n\nОбщий срок приостановления проведения выездной налоговой проверки не может превышать шесть месяцев. В случае, если проверка была приостановлена по основанию, указанному в подпункте 2 настоящего пункта, и в течение шести месяцев налоговый орган не смог получить запрашиваемую информацию от иностранных государственных органов в рамках международных договоров Российской Федерации, срок приостановления указанной проверки может быть увеличен на три месяца.\n\nНа период действия срока приостановления проведения выездной налоговой проверки приостанавливаются действия налогового органа по истребованию документов у налогоплательщика, которому в этом случае возвращаются все подлинники, истребованные при проведении проверки, за исключением документов, полученных в ходе проведения выемки, а также приостанавливаются действия налогового органа на территории (в помещении) налогоплательщика, связанные с указанной проверкой.\n\n10. Повторной выездной налоговой проверкой налогоплательщика признается выездная налоговая проверка, проводимая независимо от времени проведения предыдущей проверки по тем же налогам и за тот же период.\n\nПри назначении повторной выездной налоговой проверки ограничения, указанные в пункте 5 настоящей статьи, не действуют.\n\nПри проведении повторной выездной налоговой проверки может быть проверен период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении повторной выездной налоговой проверки.\n\nПовторная выездная налоговая проверка налогоплательщика может проводиться:\n\n1) вышестоящим налоговым органом - в порядке контроля за деятельностью налогового органа, проводившего проверку;\n\n2) налоговым органом, ранее проводившим проверку, на основании решения его руководителя (заместителя руководителя) - в случае представления налогоплательщиком уточненной налоговой декларации (расчета), в которой по сравнению с ранее представленной налоговой декларацией (расчетом) уменьшена сумма налога (сбора, страховых взносов), подлежащая уплате в бюджетную систему Российской Федерации, увеличена заявленная к возмещению сумма налога на добавленную стоимость или акциза либо увеличена сумма полученного убытка. Предметом повторной выездной налоговой проверки в указанном случае является правильность исчисления налога (сбора, страховых взносов) (определения суммы полученного убытка) на основании измененных показателей уточненной налоговой декларации (расчета), повлекших уменьшение ранее исчисленной суммы налога (сбора, страховых взносов) (увеличение заявленной к возмещению суммы налога на добавленную стоимость или акциза либо увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nЕсли при проведении повторной выездной налоговой проверки выявлен факт совершения налогоплательщиком налогового правонарушения, которое не было выявлено при проведении первоначальной выездной налоговой проверки, к налогоплательщику не применяются налоговые санкции, за исключением случаев, когда невыявление факта налогового правонарушения при проведении первоначальной налоговой проверки явилось результатом сговора между налогоплательщиком и должностным лицом налогового органа.\n\n11. Выездная налоговая проверка, осуществляемая в связи с реорганизацией или ликвидацией организации-налогоплательщика, может проводиться независимо от времени проведения и предмета предыдущей проверки. При этом проверяется период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении проверки.\n\n12. Налогоплательщик обязан обеспечить возможность должностных лиц налоговых органов, проводящих выездную налоговую проверку, ознакомиться с документами, связанными с исчислением и уплатой налогов.\n\nПри проведении выездной налоговой проверки у налогоплательщика могут быть истребованы необходимые для проверки документы в порядке, установленном статьей 93 настоящего Кодекса.\n\nОзнакомление должностных лиц налоговых органов с подлинниками документов допускается только на территории налогоплательщика, за исключением случаев проведения выездной налоговой проверки по месту нахождения налогового органа, а также случаев, предусмотренных статьей 94 настоящего Кодекса.\n\n13. При необходимости уполномоченные должностные лица налоговых органов, осуществляющие выездную налоговую проверку, могут проводить инвентаризацию имущества налогоплательщика, а также производить осмотр производственных, складских, торговых и иных помещений и территорий, используемых налогоплательщиком для извлечения дохода либо связанных с содержанием объектов налогообложения, в порядке, установленном статьей 92 настоящего Кодекса.\n\n14. При наличии у осуществляющих выездную налоговую проверку должностных лиц достаточных оснований полагать, что документы, свидетельствующие о совершении правонарушений, могут быть уничтожены, сокрыты, изменены или заменены, производится выемка этих документов в порядке, предусмотренном статьей 94 настоящего Кодекса.\n\n15. В последний день проведения выездной налоговой проверки проверяющий обязан составить справку о проведенной проверке, в которой фиксируются предмет проверки и сроки ее проведения, и вручить ее налогоплательщику или его представителю.\n\nВ случае, если налогоплательщик (его представитель) уклоняется от получения справки о проведенной проверке, указанная справка направляется налогоплательщику заказным письмом по почте.\n\n16. Особенности проведения выездных налоговых проверок при выполнении соглашений о разделе продукции определяются главой 264 настоящего Кодекса.\n\nыездных налоговых проверок резидентов, исключенных из единого реестра резидентов Особой экономической зоны в Калининградской области, определяются статьями 2881 и 3851 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 17.05.2007 № 84-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 89. Выездная налоговая проверка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8737fac2659088022c5394d59cda6accf583ffd882f3736211a13526a09d8495"},{"code_id":"NK_RF","article_number":"89.1","version_date":"2000-07-31","article_text":"1. Выездная налоговая проверка консолидированной группы налогоплательщиков проводится в отношении налога на прибыль организаций по консолидированной группе налогоплательщиков на территории (в помещении) ответственного участника этой группы и на территориях (в помещениях) иных участников этой группы на основании решения руководителя (заместителя руководителя) налогового органа.\n\nВ случае, если у участника консолидированной группы налогоплательщиков отсутствует возможность предоставить помещение для проведения выездной налоговой проверки, выездная налоговая проверка в отношении такого участника может проводиться по месту нахождения соответствующего налогового органа.\n\n2. Решение о проведении выездной налоговой проверки консолидированной группы налогоплательщиков выносит налоговый орган, осуществивший постановку на учет ответственного участника этой группы.\n\nСамостоятельная выездная налоговая проверка филиала или представительства участника консолидированной группы налогоплательщиков не проводится.\n\nВ решении о проведении выездной налоговой проверки консолидированной группы налогоплательщиков указываются:\n\nполное и сокращенное наименования ответственного участника, а также иных участников консолидированной группы налогоплательщиков (за исключением участников, в отношении которых за соответствующий период проводится (проведен) налоговый мониторинг, с учетом положений пункта 41 настоящей статьи); (В редакции Федерального закона от 03.07.2016 № 240-ФЗ)\n\nналоговые периоды, за которые проводится проверка;\n\nдолжности, фамилии и инициалы сотрудников налогового органа, которым поручается проведение проверки.\n\nДолжностные лица, указанные в решении о проведении выездной налоговой проверки консолидированной группы налогоплательщиков, могут принимать участие в проведении проверки по всем участникам консолидированной группы налогоплательщиков.\n\nФорма указанного решения утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n3. Проведение выездной налоговой проверки консолидированной группы налогоплательщиков в порядке, установленном статьей 89 настоящего Кодекса, не препятствует проведению самостоятельных выездных налоговых проверок участников этой группы по налогам, которые не подлежат исчислению и уплате указанной консолидированной группой налогоплательщиков, с отдельным оформлением результатов таких проверок.\n\n4. Предметом выездной налоговой проверки консолидированной группы налогоплательщиков является правильность исчисления и своевременность уплаты налога на прибыль организаций по этой группе.\n\n41. При проведении выездной налоговой проверки консолидированной группы налогоплательщиков налоговые органы не вправе проверять правильность определения полученных доходов и осуществленных расходов участником консолидированной группы налогоплательщиков за период, за который в отношении него проводится (проведен) налоговый мониторинг, за исключением следующих случаев:\n\n1) проведение выездной налоговой проверки вышестоящим налоговым органом в порядке контроля за деятельностью налогового органа, проводившего налоговый мониторинг;\n\n2) досрочное прекращение налогового мониторинга;\n\n3) невыполнение в срок до 1 декабря года, следующего за периодом, за который проводился налоговый мониторинг, мотивированного мнения (мотивированных мнений) налогового органа по вопросам правильности исчисления (удержания), полноты и своевременности уплаты (перечисления) налога на прибыль организаций, направленного участнику консолидированной группы налогоплательщиков, указанным участником консолидированной группы налогоплательщиков. В этом случае решение о проведении выездной налоговой проверки выносится налоговым органом не позднее двух месяцев со дня истечения указанного срока. Предметом такой выездной налоговой проверки является правильность исчисления налога на прибыль указанным участником консолидированной группы налогоплательщиков в соответствии с мотивированным мнением налогового органа; (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n4) представление ответственным участником консолидированной группы налогоплательщиков в календарном году, за который налоговый мониторинг не проводится, уточненной налоговой декларации по налогу на прибыль организаций по консолидированной группе налогоплательщиков за период проведения налогового мониторинга, в которой уменьшена сумма налога, подлежащая уплате в бюджетную систему Российской Федерации, либо увеличена сумма полученного убытка по сравнению с ранее представленной налоговой декларацией в связи с уменьшением доходов (увеличением расходов) участником консолидированной группы налогоплательщиков, в отношении которого проводился налоговый мониторинг. Предметом выездной налоговой проверки в указанном случае является правильность исчисления налога (определения суммы полученного убытка) на основании измененных показателей уточненной налоговой декларации, повлекших уменьшение ранее исчисленной суммы налога (увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\n5. Выездная налоговая проверка консолидированной группы налогоплательщиков не может продолжаться более двух месяцев. Указанный срок увеличивается на число месяцев, равное числу участников консолидированной группы налогоплательщиков (помимо ответственного участника этой группы), но не более чем до одного года.\n\n6. В случаях и порядке, которые предусмотрены пунктом 9 статьи 89 настоящего Кодекса, решение о приостановлении выездной налоговой проверки консолидированной группы налогоплательщиков выносит руководитель (заместитель руководителя) налогового органа, вынесшего решение о проведении такой проверки.\n\n7. Повторной выездной налоговой проверкой консолидированной группы налогоплательщиков признается выездная налоговая проверка, проводимая независимо от времени проведения предыдущей проверки этой группы за те же налоговые периоды.\n\n8. Справка о проведенной выездной налоговой проверке вручается представителю ответственного участника консолидированной группы налогоплательщиков в порядке, установленном пунктом 15 статьи 89 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 89.1. Особенности проведения выездной налоговой проверки консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d32dc5e2842b1e1b623e916b5cb71ecafd29bd1f6400fb720e5c18cbe051e9c"},{"code_id":"NK_RF","article_number":"89.2","version_date":"2000-07-31","article_text":"Налогоплательщик - участник регионального инвестиционного проекта, применяющий налоговые ставки по налогу на прибыль организаций, установленные пунктами 1 и 15 статьи 284 настоящего Кодекса с учетом особенностей, предусмотренных подпунктом 2 пункта 2 и подпунктом 2 пункта 3 статьи 2843 настоящего Кодекса, обязан обеспечивать сохранность данных бухгалтерского и налогового учета и других документов, указанных в настоящем пункте, на протяжении всего срока применения таких налоговых ставок.\n\n(Пункт в редакции Федерального закона от 23.05.2016 № 144-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 89.2. Особенности проведения выездной налоговой проверки налогоплательщика - участника регионального инвестиционного проекта","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1451ab6716ed17edd398e0a6adc1426e73fd0bc407e3ad4f16b083dcf9c3d89"},{"code_id":"NK_RF","article_number":"9","version_date":"2000-07-31","article_text":"Участниками отношений, регулируемых законодательством о налогах и сборах, являются:\n\n1) организации и физические лица, признаваемые в соответствии с настоящим Кодексом налогоплательщиками, плательщиками сборов, плательщиками страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n2) организации и физические лица, признаваемые в соответствии с настоящим Кодексом налоговыми агентами;\n\n3) налоговые органы (федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, и его территориальные органы); (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\n\n4) таможенные органы (федеральный орган исполнительной власти, уполномоченный в области таможенного дела, подчиненные ему таможенные органы Российской Федерации); (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 29.07.2004 № 95-ФЗ; от 26.06.2008 № 103-ФЗ)\n\n5) (Пункт утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n6) (Пункт утратил силу - Федеральный закон от 29.06.2004 № 58-ФЗ)\n\n7) (Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n8) (Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратил силу - Федеральный закон от 30.06.2003 № 86-ФЗ)","article_title":"Статья 9. Участники отношений, регулируемых законодательством о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61c5ce796343f1b22f4c2913e7b64aeef1a687f2f1b896f91c9c5c9130e3292b"},{"code_id":"NK_RF","article_number":"90","version_date":"2000-07-31","article_text":"1. В качестве свидетеля для дачи показаний может быть вызвано любое физическое лицо, которому могут быть известны какие-либо обстоятельства, имеющие значение для осуществления налогового контроля. Показания свидетеля заносятся в протокол.\n\n2. Не могут допрашиваться в качестве свидетеля:\n\n1) лица, которые в силу малолетнего возраста, своих физических или психических недостатков не способны правильно воспринимать обстоятельства, имеющие значение для осуществления налогового контроля;\n\n2) лица, которые получили информацию, необходимую для проведения налогового контроля, в связи с исполнением ими своих профессиональных обязанностей, и подобные сведения относятся к профессиональной тайне этих лиц, в частности адвокат, аудитор.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n3. Физическое лицо вправе отказаться от дачи показаний только по основаниям, предусмотренным законодательством Российской Федерации.\n\n4. Показания свидетеля могут быть получены по месту его пребывания, если он вследствие болезни, старости, инвалидности не в состоянии явиться в налоговый орган, а по усмотрению должностного лица налогового органа - и в других случаях.","article_title":"Статья 90. Участие свидетеля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2f5ef3931a51d522d37c739ac23eea4cdc64ffe5831af97da64f00047330392"},{"code_id":"NK_RF","article_number":"91","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНа основании такого акта налоговый орган по имеющимся у него данным о проверяемом лице (лице, в отношении которого проводится налоговый мониторинг) или по аналогии вправе самостоятельно определить сумму налога, подлежащую уплате. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае отказа проверяемого лица (лица, в отношении которого проводится налоговый мониторинг) подписать указанный акт в нем делается соответствующая запись. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 91. Доступ должностных лиц налоговых органов на территорию или в помещение для проведения налоговой проверки (налогового мониторинга)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ba1b0269819e923f1b450edb07d967d641deabf2b3df4646b58a7947912f17b"},{"code_id":"NK_RF","article_number":"92","version_date":"2000-07-31","article_text":"1) при проведении выездной налоговой проверки; (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n2) при проведении камеральной налоговой проверки на основе налоговой декларации в случаях, предусмотренных пунктами 8, 81 и 89 статьи 88 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n3) при проверке в рамках налогового мониторинга налоговой декларации по налогу на добавленную стоимость, в которой заявлена сумма налога к возмещению, или при выявлении противоречий или несоответствий, указанных в пунктах 81 и 89 статьи 88 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nДолжностное лицо налогового органа, принявшего предусмотренное статьей 46 настоящего Кодекса решение о взыскании задолженности, размер которой превышает 1 миллион рублей, в отношении организации, при условии, что такое решение не исполнено в течение десяти дней с даты его принятия, вправе не более одного раза по одному решению о взыскании задолженности производить осмотр территорий, помещений, документов и предметов организации при наличии ее согласия. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nОсмотр территорий, помещений, документов и предметов производится на основании мотивированного постановления должностного лица налогового органа, производящего осмотр. Указанное постановление подлежит утверждению руководителем (заместителем руководителя) налогового органа. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nПри проведении осмотра вправе участвовать лицо, территории, помещения, документы и предметы которого подлежат осмотру должностным лицом налогового органа, или его представитель, а также специалисты. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)","article_title":"Статья 92. Осмотр","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51fa0255943c79bd42341147bf9f0c05bc36cc37ee7705bb6a44ff315815e988"}]$law7d0065$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
